#pragma once
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <winsock2.h>
#include <ws2tcpip.h>
#include <string>
#include <vector>
#include <stdexcept>
#include <cstdint>
#include <cstdio>
#pragma comment(lib, "Ws2_32.lib")

static const int MAX_FRAME = 10 * 1024 * 1024;
static const unsigned int MAX_CLIP = 10 * 1024 * 1024 - 4096;
static const char CLIP_SEP[] = {'\x01','\x02','\x01','\x02'};
struct ClipDropFiles { DWORD pFiles; POINT pt; BOOL fNC; BOOL fWide; };
static std::string clip_header(unsigned int id,unsigned named,const std::string& name,size_t bytes){char h[64];int n=sprintf_s(h,sizeof(h),"%u\n%u\n%u\n",id,named,(unsigned)bytes);return std::string(h,n)+name+std::string(CLIP_SEP,4);}
static std::string utf8(const std::wstring& s) { int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),0,0,0,0); std::string r(n,0); if(n) WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),&r[0],n,0,0); return r; }
static std::wstring wide(const std::string& s) { int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),0,0); std::wstring r(n,0); if(n) MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),&r[0],n); return r; }
static bool recv_all(SOCKET s, char* p, int n) { while(n){ int k=recv(s,p,n,0); if(k<=0)return false; p+=k;n-=k;}return true; }
static bool send_all(SOCKET s,const char* p,int n){while(n){int k=send(s,p,n,0);if(k<=0)return false;p+=k;n-=k;}return true;}
static bool write_frame(SOCKET s,const std::string& secret,const std::string& cmd,const std::string& value){std::string b=secret+"\n"+cmd+"\n"+value;if(b.size()+4>MAX_FRAME)return false;uint32_t n=(uint32_t)b.size();return send_all(s,(char*)&n,4)&&send_all(s,b.data(),(int)b.size());}
static bool read_frame(SOCKET s,std::string& out){uint32_t n=0;if(!recv_all(s,(char*)&n,4)||n<1||n>MAX_FRAME)return false;out.resize(n);return recv_all(s,&out[0],(int)n);}
static bool split_frame(const std::string& b,std::string& secret,std::string& cmd,std::string& value){size_t a=b.find('\n'),c=a==std::string::npos?std::string::npos:b.find('\n',a+1);if(a==std::string::npos||c==std::string::npos)return false;secret=b.substr(0,a);cmd=b.substr(a+1,c-a-1);value=b.substr(c+1);return true;}
static void send_text(const std::wstring& text){std::vector<INPUT> a;for(wchar_t ch:text){INPUT d={};d.type=INPUT_KEYBOARD;d.ki.wScan=ch;d.ki.dwFlags=KEYEVENTF_UNICODE;a.push_back(d);d.ki.dwFlags=KEYEVENTF_UNICODE|KEYEVENTF_KEYUP;a.push_back(d);}if(!a.empty())SendInput((UINT)a.size(),a.data(),sizeof(INPUT));}
static WORD key_code(std::wstring s){for(auto& c:s)c=(wchar_t)towupper(c);if(s.size()==2&&s[0]=='F'&&s[1]>='1'&&s[1]<='9')return (WORD)(VK_F1+s[1]-'1');if(s.size()==3&&s[0]=='F'&&s[1]=='1'&&s[2]>='0'&&s[2]<='2')return (WORD)(VK_F10+(s[2]-'0'));if(s==L"SHIFT")return VK_SHIFT;if(s==L"CTRL")return VK_CONTROL;if(s==L"ALT")return VK_MENU;if(s==L"ENTER")return VK_RETURN;if(s==L"上")return VK_UP;if(s==L"下")return VK_DOWN;if(s==L"左")return VK_LEFT;if(s==L"右")return VK_RIGHT;if(s.size()==1&&s[0]>=L'A'&&s[0]<=L'Z')return (WORD)s[0];return 0;}
static bool parse_key_event(const std::string& value, WORD& vk, WORD& scan, bool& extended, bool& down){unsigned int v=0,s=0,e=0,d=0;int end=0;if(sscanf_s(value.c_str(),"%u,%u,%u,%u%n",&v,&s,&e,&d,&end)!=4||end!=(int)value.size()||v<1||v>255||s>511||e>1||d>1)return false;vk=(WORD)v;scan=(WORD)s;extended=e!=0;down=d!=0;return true;}
static bool inject_key_event(WORD vk, WORD scan, bool extended, bool down){INPUT input={};input.type=INPUT_KEYBOARD;input.ki.wVk=scan?0:vk;input.ki.wScan=scan;input.ki.dwFlags=(scan?KEYEVENTF_SCANCODE:0)|(extended?KEYEVENTF_EXTENDEDKEY:0)|(down?0:KEYEVENTF_KEYUP);return SendInput(1,&input,sizeof(input))==1;}
static bool clip_supported(UINT id){if(id==CF_UNICODETEXT||id==CF_TEXT||id==CF_OEMTEXT||id==CF_DIB||id==CF_DIBV5||id==CF_TIFF||id==CF_HDROP)return true;wchar_t name[256]={};if(!GetClipboardFormatNameW(id,name,256))return false;return name[0]!=0;}
static bool clip_is_name(UINT id){return id>0xFFFF||(id!=CF_UNICODETEXT&&id!=CF_TEXT&&id!=CF_OEMTEXT&&id!=CF_DIB&&id!=CF_DIBV5&&id!=CF_TIFF&&id!=CF_HDROP);}
static std::string clip_data(UINT id,size_t& skipped){HANDLE h=GetClipboardData(id);if(!h){skipped=1;return{};}SIZE_T size=GlobalSize(h);if(size<1||size>MAX_CLIP){skipped=1;return{};}void* p=GlobalLock(h);if(!p){skipped=1;return{};}std::string data((const char*)p,size);GlobalUnlock(h);return data;}
static bool clip_dropfiles_unicode(const std::string& data){if(data.size()<sizeof(ClipDropFiles))return false;const ClipDropFiles* df=(const ClipDropFiles*)data.data();return (df->fWide&1)!=0;}
static std::vector<std::wstring> clip_dropfiles_names(const std::string& data){std::vector<std::wstring> out;if(data.size()<sizeof(ClipDropFiles))return out;const ClipDropFiles* df=(const ClipDropFiles*)data.data();size_t off=df->pFiles;if(off>=data.size())return out;const char* base=data.data()+off;size_t remain=data.size()-off;if(df->fWide&1){const wchar_t* w=(const wchar_t*)base;size_t n=remain/2;for(size_t i=0;i<n&&w[i];){std::wstring one(&w[i]);if(!one.empty())out.push_back(one);i+=one.size()+1;}}else{for(size_t i=0;i<remain&&base[i];){std::string one(&base[i]);if(!one.empty())out.push_back(wide(one));i+=one.size()+1;}}return out;}
static bool clip_read_file(const std::wstring& path,std::string& out){HANDLE h=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ,0,OPEN_EXISTING,0,0);if(h==INVALID_HANDLE_VALUE)return false;LARGE_INTEGER size={};if(!GetFileSizeEx(h,&size)||size.QuadPart<0||size.QuadPart>(LONGLONG)MAX_CLIP){CloseHandle(h);return false;}out.resize((size_t)size.QuadPart);DWORD got=0,total=0;bool ok=true;while(total<out.size()){if(!ReadFile(h,&out[total],(DWORD)(out.size()-total),&got,0)||got==0){ok=false;break;}total+=got;}CloseHandle(h);return ok;}
static std::string clip_dropfiles_buffer(const std::vector<std::wstring>& names){size_t chars=1;for(const std::wstring& n:names)chars+=n.size()+1;size_t bytes=chars*2;std::string out(sizeof(ClipDropFiles)+bytes,0);ClipDropFiles* df=(ClipDropFiles*)&out[0];df->pFiles=(DWORD)sizeof(ClipDropFiles);df->fWide=1;wchar_t* w=(wchar_t*)(&out[0]+sizeof(ClipDropFiles));for(const std::wstring& n:names){memcpy(w,n.c_str(),(n.size()+1)*2);w+=n.size()+1;}*w=0;return out;}
static bool clip_transfer_files(const std::string& data,std::string& out){std::vector<std::wstring> names=clip_dropfiles_names(data);if(names.empty())return false;std::string body;std::string encoded;for(const std::wstring& n:names){if(!clip_read_file(n,encoded))continue;std::string utf8name=utf8(n);char head[64];int hn=sprintf_s(head,sizeof(head),"%u\n%u\n",utf8name.size(),encoded.size());if(body.size()+encoded.size()+utf8name.size()+hn+64>MAX_CLIP)break;body.append(head,hn).append(utf8name).append(encoded);}if(body.empty())return false;std::string list=clip_dropfiles_buffer(names);char head[64];int hn=sprintf_s(head,sizeof(head),"%u\n%u\n",list.size(),body.size());out.assign(head,hn).append(list).append(body);return true;}
static std::string clip_serialize(bool& skipped){skipped=false;if(!OpenClipboard(0))return{};UINT id=0;std::string out;bool text=false;for(;;){id=EnumClipboardFormats(id);if(!id)break;if(!clip_supported(id)){skipped=true;continue;}if(text&&(id==CF_TEXT||id==CF_OEMTEXT))continue;size_t skip=0;std::string data;if(id==CF_HDROP){data=clip_data(id,skip);std::string transfer;if(!clip_transfer_files(data,transfer)){skipped=true;continue;}data=transfer;}else{data=clip_data(id,skip);if(skip){skipped=true;continue;}}bool named=clip_is_name(id);std::string utf8name;if(named){wchar_t name[256]={};GetClipboardFormatNameW(id,name,256);int wn=WideCharToMultiByte(CP_UTF8,0,name,-1,0,0,0,0);utf8name.assign(wn>0?wn-1:0,0);if(wn>1)WideCharToMultiByte(CP_UTF8,0,name,-1,&utf8name[0],wn,0,0);}if(out.size()+data.size()+utf8name.size()+64>MAX_CLIP){skipped=true;break;}out+=clip_header(id,named?1:0,utf8name,data.size());out+=data;if(id==CF_UNICODETEXT)text=true;}CloseClipboard();return out;}
static bool clip_parse_one(const std::string& data,size_t& pos,unsigned int& id,bool& named,std::string& name,std::string& bytes){size_t a=data.find('\n',pos);if(a==std::string::npos)return false;size_t b=data.find('\n',a+1);if(b==std::string::npos)return false;size_t c=data.find('\n',b+1);if(c==std::string::npos)return false;size_t sep=data.find(CLIP_SEP,c+1);if(sep==std::string::npos)return false;id=(unsigned int)atoi(data.substr(pos,a-pos).c_str());named=atoi(data.substr(a+1,b-a-1).c_str())!=0;unsigned int length=(unsigned int)atoi(data.substr(b+1,c-b-1).c_str());name=data.substr(c+1,sep-c-1);if(length>MAX_CLIP||sep+4+length>data.size())return false;bytes=data.substr(sep+4,length);pos=sep+4+length;return true;}
static bool clip_rebuild_files(const std::string& data,std::string& out){size_t a=data.find('\n');if(a==std::string::npos){fprintf(stderr,"DBG npos1\n");return false;}size_t b=data.find('\n',a+1);if(b==std::string::npos){fprintf(stderr,"DBG npos2\n");return false;}unsigned int listlen=(unsigned int)atoi(data.substr(0,a).c_str()),bodylen=(unsigned int)atoi(data.substr(a+1,b-a-1).c_str());if(listlen<sizeof(ClipDropFiles)||b+1+listlen+bodylen!=data.size())return false;std::string list=data.substr(b+1,listlen);std::string body=data.substr(b+1+listlen);wchar_t dir[MAX_PATH];if(!GetTempPathW(MAX_PATH,dir))return false;std::wstring folder=std::wstring(dir)+L"WinInput\\";CreateDirectoryW(folder.c_str(),0);std::vector<std::wstring> written;size_t pos=0;while(pos<body.size()){size_t a2=body.find('\n',pos);if(a2==std::string::npos)break;size_t b2=body.find('\n',a2+1);if(b2==std::string::npos)break;unsigned int namelen=(unsigned int)atoi(body.substr(pos,a2-pos).c_str()),filelen=(unsigned int)atoi(body.substr(a2+1,b2-a2-1).c_str());if(b2+1+namelen+filelen>body.size())break;std::wstring path=wide(body.substr(b2+1,namelen));std::string content=body.substr(b2+1+namelen,filelen);pos=b2+1+namelen+filelen;const wchar_t* base=path.c_str();const wchar_t* leaf=wcsrchr(base,L'\\');leaf=leaf?leaf+1:base;std::wstring target=folder+leaf;HANDLE f=CreateFileW(target.c_str(),GENERIC_WRITE,0,0,CREATE_ALWAYS,0,0);if(f==INVALID_HANDLE_VALUE)continue;DWORD wrote=0;bool ok=true;if(!content.empty()&&(!WriteFile(f,content.data(),(DWORD)content.size(),&wrote,0)||wrote!=content.size()))ok=false;CloseHandle(f);if(ok)written.push_back(target);}if(written.empty())return false;out=clip_dropfiles_buffer(written);return true;}
static bool clip_write_entry(UINT id,bool named,const std::string& name,const std::string& bytes){UINT format=named?RegisterClipboardFormatW(wide(name).c_str()):id;if(!format)return false;std::string payload=bytes;if(id==CF_HDROP){std::string rebuilt;if(clip_rebuild_files(bytes,rebuilt))payload=rebuilt;}HGLOBAL global=GlobalAlloc(GMEM_MOVEABLE,payload.size());if(!global)return false;void* p=GlobalLock(global);if(!p){GlobalFree(global);return false;}memcpy(p,payload.data(),payload.size());GlobalUnlock(global);if(!SetClipboardData(format,global)){GlobalFree(global);return false;}return true;}
static int clip_deserialize(const std::string& data){if(!OpenClipboard(0))return -1;EmptyClipboard();int count=0;size_t pos=0;unsigned int id;bool named;std::string name,bytes;while(clip_parse_one(data,pos,id,named,name,bytes))if(clip_write_entry(id,named,name,bytes))++count;CloseClipboard();return count;}
static void send_key(const std::wstring& value){std::vector<WORD> keys;size_t p=0;while(p<value.size()){size_t q=value.find(L'+',p);std::wstring part=value.substr(p,q==std::wstring::npos?std::wstring::npos:q-p);WORD k=key_code(part);if(!k)return;keys.push_back(k);if(q==std::wstring::npos)break;p=q+1;}std::vector<INPUT> a;for(WORD k:keys){INPUT i={};i.type=INPUT_KEYBOARD;i.ki.wVk=k;if(k==VK_UP||k==VK_DOWN||k==VK_LEFT||k==VK_RIGHT)i.ki.dwFlags=KEYEVENTF_EXTENDEDKEY;a.push_back(i);}for(auto i=keys.rbegin();i!=keys.rend();++i){INPUT x={};x.type=INPUT_KEYBOARD;x.ki.wVk=*i;x.ki.dwFlags=KEYEVENTF_KEYUP;if(*i==VK_UP||*i==VK_DOWN||*i==VK_LEFT||*i==VK_RIGHT)x.ki.dwFlags|=KEYEVENTF_EXTENDEDKEY;a.push_back(x);}if(!a.empty())SendInput((UINT)a.size(),a.data(),sizeof(INPUT));}
